#include <print>
#include <vector>

std::vector<int> cur;
void dfs(int start) {
    if (cur.size() == 3) {
        std::println("{} {} {}", cur[0], cur[1], cur[2]);
        return;
    }
    for (int i = start; i <= 5; ++i) {
        cur.push_back(i);
        dfs(1);   // 门槛退回 1，同一层又能挑刚挑过的数，先冒出 1 1
        cur.pop_back();
    }
}
int main() { dfs(1); }

