    if (cur.size() == 2) {
        std::println("{} {}", cur[0], cur[1]);
        return;
    }
    for (int i = start; i <= 4; ++i) {
        cur.push_back(i);
        dfs(i + 1);
        cur.pop_back();
    }
}
